-- publishers ---------------------------------------------------------------

   'Refuses the drum on principle and the reverb on principle too. Records at 4am in a tiled hallway because ''the walls already know the maqām''. Twelve releases, all of them quiet.', 'Madinah → Istanbul', 'yusuf-karim', 'jade', 'listener', 'artist', true, now() - interval '400 days'),
  ('708aefa0-2a83-42c1-b120-74393eb8838f', 'rawda', 'Al-Rawḍa Ensemble', 'فرقة الروضة', 'seven voices & duff',
   'A Cairo gathering that turned into an ensemble in 1998 and never quite stopped. Three generations of singers, one frame drum older than two of them, and a standing rule: whoever arrives first leads.', 'Cairo', 'rawda-ensemble', 'gold', 'listener', 'artist', true, now() - interval '497 days'),
  ('9c8447d4-3b58-4ec3-b714-abe627b4d5bf', 'hanan', 'Hanan Siddiqui', 'حنان صديقي', 'voice & duff',
   'Sings for women''s gatherings and for the last third of the night. Known for Ṣabā — the maqām of tears — and for stopping mid-phrase when the room gets too loud.', 'Birmingham → Amman', 'hanan-siddiqui', 'madder', 'listener', 'artist', true, now() - interval '594 days'),
  ('f25def6c-4b05-46c7-9412-8a36a7defa71', 'muadh', 'Muʿādh & the Night Choir', 'معاذ وكورال الليل', 'choir & frame drum',
   'Twelve singers who only meet after ʿIshāʾ. They record standing in a circle, once, no edits, and whatever the room does that night is on the record.', 'Kuala Lumpur', 'muadh-night-choir', 'cobalt', 'listener', 'artist', false, now() - interval '691 days'),
  ('21f49ce5-69d5-4d23-a032-260eabbac935', 'ibrahim', 'Ibrahim Folarin', 'إبراهيم فولارين', 'voice, claps & duff',
   'Carries the West African qaṣīda tradition into the street: call-and-response, hand claps behind the beat, and a drum that is allowed to be happy.', 'Sokoto → Lagos', 'ibrahim-folarin', 'madder', 'listener', 'artist', false, now() - interval '788 days'),
  ('4956df2f-a907-45e1-9fc9-df8d99f3af99', 'halabi', 'ʿAbdurraḥmān al-Ḥalabī', 'عبد الرحمن الحلبي', 'voice & qaṣīda',
   'Sings the Burda the way Aleppo still teaches it, quarter tones intact. Will not use a metronome; says the phrase knows its own length.', 'Aleppo → Konya', 'halabi-qasida', 'gold', 'listener', 'artist', true, now() - interval '885 days'),
  ('3782b37c-b00f-4146-83f7-0d2934b37ddb', 'sami', 'Sami Deen', 'سامي دين', 'voice & loops',
   'Makes minimal devotional music in a basement with one microphone. Writes his own words. Believes a nasheed should be able to survive being whispered.', 'Toronto', 'sami-deen', 'jade', 'listener', 'artist', false, now() - interval '982 days'),
  ('81a8cef1-c501-4fa7-bb04-aab67d6430cf', 'zayd', 'Zayd Amīn', 'زيد أمين', 'voice & story',
   'Storyteller first, singer second. His tracks are long, they have plots, and they always end somewhere quieter than they started.', 'Sarajevo', 'zayd-amin', 'turq', 'listener', 'artist', false, now() - interval '1079 days')
on conflict (id) do nothing;

