  ('sng_talaa-al-badru', '708aefa0-2a83-42c1-b120-74393eb8838f', 'Ṭalaʿa al-Badru ʿAlaynā', 'طلع البدر علينا', 'The oldest welcome song in the tradition — sung for the Prophet ﷺ as he entered Madinah. Seven voices, one frame drum, no other instruments.',
   'rast', 55, 84, 'choir', 'D..T..D.T..T.D..', 'intro',
   2, 'gold', 2019, array['welcome', 'classical', 'madinah', 'choir']::text[], '[{"tr":"Ṭalaʿa al-badru ʿalaynā","ar":"طَلَعَ البَدْرُ عَلَيْنَا","en":"The full moon rose upon us","note":"traditional"},{"tr":"Min thaniyyāti al-wadāʿ","ar":"مِنْ ثَنِيَّاتِ الوَدَاعِ","en":"from the passes of al-Wadāʿ"},{"tr":"Wajaba al-shukru ʿalaynā","ar":"وَجَبَ الشُّكْرُ عَلَيْنَا","en":"Gratitude became binding upon us"},{"tr":"Mā daʿā lillāhi dāʿ","ar":"مَا دَعَا لِلَّهِ دَاعٍ","en":"for as long as a caller calls to Allah"},{"tr":"Ayyuhā al-mabʿūthu fīnā","ar":"أَيُّهَا المَبْعُوثُ فِينَا","en":"O you who were sent among us"},{"tr":"Jiʾta bi-l-amri al-muṭāʿ","ar":"جِئْتَ بِالأَمْرِ المُطَاعِ","en":"you came with a command obeyed"},{"tr":"Ṭalaʿa al-badru ʿalaynā","ar":"طَلَعَ البَدْرُ عَلَيْنَا","en":"The full moon rose upon us","note":"refrain"}]'::jsonb, null,
   null, null, null, 98429, null, 'live', now() - interval '43 days', 27850, 771, 0),
  ('sng_ya-nabi-salam', 'd26f258b-7b1d-452b-bf5a-7947d45fb56b', 'Yā Nabiyy Salām ʿAlayka', 'يا نبيّ سلام عليك', 'A Ḥijāz greeting in two voices, recorded in a single take with no duff at all — the way Yusuf insists it should be heard.',
   'hijaz', 57, 70, 'duet', null, 'verse',
   2, 'jade', 2021, array['salawat', 'classical', 'vocals only', 'night']::text[], '[{"tr":"Yā Nabiyy salāmun ʿalayka","ar":"يَا نَبِيِّ سَلَامٌ عَلَيْكَ","en":"O Prophet, peace be upon you","note":"traditional"},{"tr":"Yā Rasūla salāmun ʿalayka","ar":"يَا رَسُولَ سَلَامٌ عَلَيْكَ","en":"O Messenger, peace be upon you"},{"tr":"Yā Ḥabība salāmun ʿalayka","ar":"يَا حَبِيبَ سَلَامٌ عَلَيْكَ","en":"O beloved, peace be upon you"},{"tr":"Ṣalawātu Allāhi ʿalayka","ar":"صَلَوَاتُ اللهِ عَلَيْكَ","en":"the blessings of Allah be upon you"},{"tr":"Ashraqa al-badru ʿalaynā","ar":"أَشْرَقَ البَدْرُ عَلَيْنَا","en":"The moon shone out upon us"},{"tr":"Fa-khtafat minhu al-budūru","ar":"فَاخْتَفَتْ مِنْهُ البُدُورُ","en":"and all other moons withdrew"},{"tr":"Mithla ḥusnikum mā raʾaynā","ar":"مِثْلَ حُسْنِكُمْ مَا رَأَيْنَا","en":"Beauty like yours we have never seen"},{"tr":"Qaṭṭu yā wajha al-surūri","ar":"قَطُّ يَا وَجْهَ السُّرُورِ","en":"never, O face of joy"}]'::jsonb, null,
   null, null, null, 150343, null, 'live', now() - interval '79 days', 11731, 366, 0),
  ('sng_mawlaya-salli', '4956df2f-a907-45e1-9fc9-df8d99f3af99', 'Mawlāya Ṣalli wa Sallim', 'مولاي صلّ وسلّم', 'The Aleppine refrain that opens a thousand gatherings, in maqām Bayātī with quarter tones left exactly where they ache.',
   'bayati', 55, 66, 'duet', 'D.......D...T...', 'verse',
   2, 'gold', 2018, array['salawat', 'classical', 'bayati']::text[], '[{"tr":"Mawlāya ṣalli wa sallim dāʾiman abadā","ar":"مَوْلَايَ صَلِّ وَسَلِّمْ دَائِمًا أَبَدًا","en":"My Lord, send blessings and peace, always, forever","note":"traditional"},{"tr":"ʿAlā ḥabībika khayri al-khalqi kullihimi","ar":"عَلَى حَبِيبِكَ خَيْرِ الخَلْقِ كُلِّهِمِ","en":"upon Your beloved, the best of all creation"},{"tr":"Huwa al-ḥabību alladhī turjā shafāʿatuhu","ar":"هُوَ الحَبِيبُ الَّذِي تُرْجَى شَفَاعَتُهُ","en":"He is the beloved whose intercession is hoped for","note":"al-Burda"},{"tr":"Li-kulli hawlin mina al-ahwāli muqtaḥimi","ar":"لِكُلِّ هَوْلٍ مِنَ الأَهْوَالِ مُقْتَحِمِ","en":"against every terror of terrors that breaks over us"},{"tr":"Mawlāya ṣalli wa sallim dāʾiman abadā","ar":"مَوْلَايَ صَلِّ وَسَلِّمْ دَائِمًا أَبَدًا","en":"My Lord, send blessings and peace, always, forever","note":"refrain"}]'::jsonb, null,
   null, null, null, 140545, null, 'live', now() - interval '104 days', 7985, 338, 0),
  ('sng_burda-dhi-salam', '4956df2f-a907-45e1-9fc9-df8d99f3af99', 'al-Burda: Bi-Dhī Salam', 'البردة: بذي سلم', 'The opening of al-Būṣīrī''s 13th-century Burda — tears remembered at the campsite of Dhī Salam. Sung unaccompanied, as a qaṣīda should be.',
   'nahawand', 53, 76, 'solo', null, 'verse',
   2, 'madder', 2017, array['classical', 'qasida', 'longing', 'solo']::text[], '[{"tr":"Amin tadhakkuri jīrānin bi-Dhī Salam","ar":"أَمِنْ تَذَكُّرِ جِيرَانٍ بِذِي سَلَمٍ","en":"Is it from remembering neighbours at Dhī Salam","note":"al-Būṣīrī, d. 1294"},{"tr":"Mazajta damʿan jarā min muqlatin bidami","ar":"مَزَجْتَ دَمْعًا جَرَى مِنْ مُقْلَةٍ بِدَمِ","en":"that you mixed tears running from your eye with blood?"},{"tr":"Am habbati al-rīḥu min tilqāʾi Kāẓimatin","ar":"أَمْ هَبَّتِ الرِّيحُ مِنْ تِلْقَاءِ كَاظِمَةٍ","en":"Or did the wind blow from the direction of Kāẓima"},{"tr":"Wa awmaḍa al-barqu fī al-ẓalmāʾi min Iḍam","ar":"وَأَوْمَضَ البَرْقُ فِي الظَّلْمَاءِ مِنْ إِضَمِ","en":"and lightning flash in the dark above Iḍam?"},{"tr":"Fa-mā li-ʿaynayka in qulta ikfufā hamatā","ar":"فَمَا لِعَيْنَيْكَ إِنْ قُلْتَ اكْفُفَا هَمَتَا","en":"Then what ails your eyes — you say ''be still'' and they pour"},{"tr":"Wa-mā li-qalbika in qulta istafiq yahimi","ar":"وَمَا لِقَلْبِكَ إِنْ قُلْتَ اسْتَفِقْ يَهِمِ","en":"and what ails your heart — you say ''wake up'' and it wanders?"}]'::jsonb, null,
   null, null, null, 148579, null, 'live', now() - interval '147 days', 15528, 738, 0),
  ('sng_nur-ala-nur', 'd26f258b-7b1d-452b-bf5a-7947d45fb56b', 'Nūrun ʿalā Nūr', 'نور على نور', 'The Āyat al-Nūr set for a low choir. Nothing hurries here — the phrase ends where the breath ends.',
   'hijazkar', 50, 58, 'choir', null, 'verse',
   2, 'turq', 2022, array['quran', 'light', 'stillness', 'choir']::text[], '[{"tr":"Allāhu nūru al-samāwāti wa-l-arḍ","ar":"اللهُ نُورُ السَّمَاوَاتِ وَالأَرْضِ","en":"Allah is the Light of the heavens and the earth","note":"Qurʾān 24:35"},{"tr":"Mathalu nūrihī ka-mishkātin","ar":"مَثَلُ نُورِهِ كَمِشْكَاةٍ","en":"The likeness of His light is a niche","note":"Qurʾān 24:35"},{"tr":"Fīhā miṣbāḥun","ar":"فِيهَا مِصْبَاحٌ","en":"in which there is a lamp"},{"tr":"Al-miṣbāḥu fī zujājatin","ar":"المِصْبَاحُ فِي زُجَاجَةٍ","en":"the lamp within a glass"},{"tr":"Nūrun ʿalā nūrin","ar":"نُورٌ عَلَى نُورٍ","en":"light upon light"},{"tr":"Yahdī Allāhu li-nūrihī man yashāʾu","ar":"يَهْدِي اللهُ لِنُورِهِ مَنْ يَشَاءُ","en":"Allah guides to His light whom He wills","note":"Qurʾān 24:35"}]'::jsonb, null,
   null, null, null, 149172, null, 'live', now() - interval '212 days', 14593, 314, 0),
  ('sng_qad-jaakum-rasul', '21f49ce5-69d5-4d23-a032-260eabbac935', 'Qad Jāʾakum Rasūl', 'لقد جاءكم رسول', 'Sokoto''s call-and-response setting of the āyah that calls the Messenger ﷺ ''grievous for him is what you suffer''. Hand claps, one drum, no more.',
   'ushshaq', 52, 72, 'duet', 'D...T...D...T...', 'verse',
   2, 'madder', 2020, array['quran', 'mercy', 'west africa', 'duet']::text[], '[{"tr":"Laqad jāʾakum rasūlun min anfusikum","ar":"لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ","en":"There has come to you a Messenger from among yourselves","note":"Qurʾān 9:128"},{"tr":"ʿAzīzun ʿalayhi mā ʿanittum","ar":"عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ","en":"heavy upon him is what you suffer"},{"tr":"Ḥarīṣun ʿalaykum","ar":"حَرِيصٌ عَلَيْكُمْ","en":"concerned for you, above all"},{"tr":"Bi-l-muʾminīna raʾūfun raḥīmun","ar":"بِالمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ","en":"to the believers, kind and merciful"},{"tr":"Ḥasbiya Allāhu lā ilāha illā Huwa","ar":"حَسْبِيَ اللهُ لَا إِلَهَ إِلَّا هُوَ","en":"Allah is sufficient for me — there is no god but He","note":"Qurʾān 9:129"},{"tr":"ʿAlayhi tawakkaltu","ar":"عَلَيْهِ تَوَكَّلْتُ","en":"upon Him I rely"}]'::jsonb, null,
