  ('sng_subhanallah-bihamdihi', 'f25def6c-4b05-46c7-9412-8a36a7defa71', 'Subḥān Allāh wa bi-Ḥamdih', 'سبحان الله وبحمده', 'Built for the 100th repetition. The Night Choir keeps the phrase almost flat so the mind can settle into it.',
   'kurd', 55, 64, 'choir', null, 'verse',
   3, 'cobalt', 2023, array['dhikr', 'stillness', 'night choir', 'loop']::text[], '[{"tr":"Subḥāna Allāhi wa bi-ḥamdih","ar":"سُبْحَانَ اللهِ وَبِحَمْدِهِ","en":"Glory be to Allah, and praise","note":"dhikr"},{"tr":"Subḥāna Allāhi al-ʿaẓīm","ar":"سُبْحَانَ اللهِ العَظِيمِ","en":"glory be to Allah, the Magnificent"},{"tr":"Subḥāna Allāhi wa bi-ḥamdih","ar":"سُبْحَانَ اللهِ وَبِحَمْدِهِ","en":"Glory be to Allah, and praise"},{"tr":"ʿAdada khalqihī wa riḍā nafsih","ar":"عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ","en":"as many as His creation, and as much as pleases Him"},{"tr":"Wa zinata ʿarshihī wa midāda kalimātih","ar":"وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","en":"the weight of His throne, the ink of His words"},{"tr":"Subḥāna Allāhi al-ʿaẓīm","ar":"سُبْحَانَ اللهِ العَظِيمِ","en":"glory be to Allah, the Magnificent"}]'::jsonb, null,
