   3, 'cobalt', 2023, array['dhikr', 'declaration', 'duff', 'choir']::text[], '[{"tr":"Lā ilāha illā Allāh","ar":"لَا إِلَهَ إِلَّا اللهُ","en":"There is no god but Allah","note":"dhikr"},{"tr":"Muḥammadun Rasūlu Allāh","ar":"مُحَمَّدٌ رَسُولُ اللهِ","en":"Muḥammad is the Messenger of Allah"},{"tr":"Lā ilāha illā Allāh","ar":"لَا إِلَهَ إِلَّا اللهُ","en":"There is no god but Allah"},{"tr":"Ḥayya ʿalā al-falāḥ","ar":"حَيٌّ عَلَى الفَلَاحِ","en":"come to success","note":"from the adhān"},{"tr":"Lā ilāha illā Allāh","ar":"لَا إِلَهَ إِلَّا اللهُ","en":"There is no god but Allah"},{"tr":"Waḥdahu lā sharīka lah","ar":"وَحْدَهُ لَا شَرِيكَ لَهُ","en":"alone, without partner"}]'::jsonb, null,
