  ('sng_allahumma-salli', '708aefa0-2a83-42c1-b120-74393eb8838f', 'Allāhumma Ṣalli ʿalā Muḥammad', 'اللهمّ صلّ على محمد', 'A bright, open ṣalāt in maqām ʿAjam — the one the ensemble uses to close their Friday gathering.',
   'ajam', 57, 78, 'choir', 'D...T...D.T.....', 'verse',
   2, 'gold', 2016, array['salawat', 'choir', 'classical']::text[], '[{"tr":"Allāhumma ṣalli ʿalā Muḥammad","ar":"اللهُمَّ صَلِّ عَلَى مُحَمَّدٍ","en":"O Allah, send blessings upon Muḥammad","note":"ṣalāt"},{"tr":"Wa ʿalā āli Muḥammad","ar":"وَعَلَى آلِ مُحَمَّدٍ","en":"and upon the family of Muḥammad"},{"tr":"Kamā ṣallayta ʿalā Ibrāhīm","ar":"كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ","en":"as You sent blessings upon Ibrāhīm"},{"tr":"Wa ʿalā āli Ibrāhīm","ar":"وَعَلَى آلِ إِبْرَاهِيمَ","en":"and upon the family of Ibrāhīm"},{"tr":"Innaka ḥamīdun majīd","ar":"إِنَّكَ حَمِيدٌ مَجِيدٌ","en":"indeed You are praiseworthy and glorious"},{"tr":"Allāhumma ṣalli ʿalā Muḥammad","ar":"اللهُمَّ صَلِّ عَلَى مُحَمَّدٍ","en":"O Allah, send blessings upon Muḥammad","note":"refrain"}]'::jsonb, null,
   null, null, null, 104769, null, 'live', now() - interval '369 days', 20052, 728, 0),
  ('sng_asma-al-husna', '708aefa0-2a83-42c1-b120-74393eb8838f', 'Asmāʾ al-Ḥusnā', 'الأسماء الحسنى', 'Nine of the beautiful names, each given a full bar. The ensemble slows by four beats per name until the last one barely moves.',
   'ajam', 53, 60, 'choir', null, 'verse',
   2, 'turq', 2015, array['names', 'stillness', 'choir', 'sleep']::text[], '[{"tr":"Al-Raḥmānu al-Raḥīm","ar":"الرَّحْمَنُ الرَّحِيمُ","en":"The All-Merciful, the Most Merciful","note":"names"},{"tr":"Al-Maliku al-Quddūs","ar":"المَلِكُ القُدُّوسُ","en":"The Sovereign, the Most Pure"},{"tr":"Al-Salāmu al-Muʾmin","ar":"السَّلَامُ المُؤْمِنُ","en":"The Source of Peace, the Giver of Safety"},{"tr":"Al-ʿAzīzu al-Jabbār","ar":"العَزِيزُ الجَبَّارُ","en":"The Almighty, the Restorer"},{"tr":"Al-Khāliqu al-Bāriʾ","ar":"الخَالِقُ البَارِئُ","en":"The Creator, the Originator"},{"tr":"Al-Muṣawwiru al-Ghafūr","ar":"المُصَوِّرُ الغَفُورُ","en":"The Fashioner, the Ever-Forgiving"},{"tr":"Al-Wadūdu al-Nūr","ar":"الوَدُودُ النُّورُ","en":"The Most Loving, the Light"},{"tr":"Al-Hādī al-Raḥīm","ar":"الهَادِي الرَّحِيمُ","en":"The Guide, the Merciful"}]'::jsonb, null,
   null, null, null, 151400, null, 'live', now() - interval '415 days', 6472, 240, 0),
  ('sng_astaghfirullah', '9c8447d4-3b58-4ec3-b714-abe627b4d5bf', 'Astaghfirullāh al-ʿAẓīm', 'أستغفر الله العظيم', 'Recorded in the last third of a Ramadan night. Ṣabā is the maqām of tears; Hanan uses it like one.',
   'saba', 52, 68, 'solo', null, 'verse',
   3, 'madder', 2022, array['dhikr', 'istighfar', 'ramadan', 'solo']::text[], '[{"tr":"Astaghfiru Allāha al-ʿaẓīm","ar":"أَسْتَغْفِرُ اللهَ العَظِيمَ","en":"I seek the forgiveness of Allah, the Magnificent","note":"dhikr"},{"tr":"Wa atūbu ilayh","ar":"وَأَتُوبُ إِلَيْهِ","en":"and I turn back to Him"},{"tr":"Astaghfiru Allāha al-ʿaẓīm","ar":"أَسْتَغْفِرُ اللهَ العَظِيمَ","en":"I seek the forgiveness of Allah, the Magnificent"},{"tr":"Alladhī lā ilāha illā Huwa","ar":"الَّذِي لَا إِلَهَ إِلَّا هُوَ","en":"there is no god but He"},{"tr":"Al-Ḥayyu al-Qayyūm","ar":"الحَيُّ القَيُّومُ","en":"the Ever-Living, the Sustainer"},{"tr":"Wa atūbu ilayh","ar":"وَأَتُوبُ إِلَيْهِ","en":"and I turn back to Him"}]'::jsonb, null,
   null, null, null, 179559, null, 'live', now() - interval '443 days', 5332, 229, 0),
  ('sng_sakina', '9c8447d4-3b58-4ec3-b714-abe627b4d5bf', 'Sakīna', 'سكينة', 'An original lullaby for the anxious heart. Six lines, fifty-six beats a minute, no drum anywhere near it.',
   'nahawand', 50, 56, 'solo', null, 'verse',
   2, 'turq', 2021, array['original', 'stillness', 'sleep', 'night']::text[], '[{"en":"Put down the day, it is heavier than you","note":"original"},{"en":"The lamp is low, the house is breathing slow"},{"tr":"Sakīna, sakīna","ar":"سَكِينَةٌ سَكِينَةٌ","en":"Stillness, stillness"},{"en":"comes down the stairs of the night to find you"},{"en":"You are not the sum of what went wrong today"},{"en":"The sky keeps its own count, and it is mercy"},{"tr":"Sakīna, sakīna","ar":"سَكِينَةٌ سَكِينَةٌ","en":"Stillness, stillness"}]'::jsonb, null,
   null, null, null, 169071, null, 'live', now() - interval '497 days', 26529, 687, 0),
  ('sng_city-of-fajr', '3782b37c-b00f-4146-83f7-0d2934b37ddb', 'City of Fajr', null, 'Written on a night bus: the whole city asleep except the mosques. Two voices, one drum, a quarter tone that never resolves.',
   'bayati', 55, 74, 'duet', 'D..T..D.T..T.D..', 'verse',
   2, 'jade', 2024, array['original', 'dawn', 'city', 'duet']::text[], '[{"en":"The city sleeps under one green light","note":"original"},{"en":"and the minarets are already awake"},{"tr":"Yā Fajr, yā Fajr","ar":"يا فجر يا فجر","en":"O dawn, o dawn"},{"en":"wash the streets of what they took from us"},{"en":"I am walking home with wet shoes and a dry heart"},{"en":"the call to prayer is the only thing on time"},{"tr":"Yā Fajr, yā Fajr","ar":"يا فجر يا فجر","en":"O dawn, o dawn"}]'::jsonb, null,
   null, null, null, 118216, null, 'live', now() - interval '536 days', 24237, 785, 0),
  ('sng_ya-rabb', '9c8447d4-3b58-4ec3-b714-abe627b4d5bf', 'Yā Rabb', 'يا ربّ', 'A duʿāʾ with no answer in it — the asking is the whole song.',
   'hijaz', 53, 62, 'solo', null, 'verse',
   2, 'madder', 2020, array['original', 'dua', 'solo', 'night']::text[], '[{"tr":"Yā Rabb, yā Rabb","ar":"يا ربّ يا ربّ","en":"O Lord, o Lord","note":"original"},{"en":"I have nothing clean to bring You"},{"en":"so I bring the thing I broke"},{"tr":"Yā Rabb, yā Rabb","ar":"يا ربّ يا ربّ","en":"O Lord, o Lord"},{"en":"You are closer than the word I use for You"},{"en":"hold what I cannot hold"}]'::jsonb, null,
   null, null, null, 108581, null, 'live', now() - interval '582 days', 18397, 520, 0),
  ('sng_ramadan-ya-nur', '21f49ce5-69d5-4d23-a032-260eabbac935', 'Ramaḍān Yā Nūr', 'رمضان يا نور', 'Lagos street nasheed for the first sighting of the moon — the fastest thing in this catalogue and the happiest.',
   'rast', 57, 92, 'choir', 'D..TD..TD.T.D..T', 'intro',
   2, 'gold', 2023, array['ramadan', 'celebration', 'duff', 'choir']::text[], '[{"tr":"Ramaḍān yā nūr, yā nūr al-bayt","ar":"رمضان يا نور، يا نور البيت","en":"Ramadan, o light — light of the house","note":"original"},{"en":"the moon was seen, the lamps are on"},{"en":"my mother is awake before everyone"},{"tr":"Ramaḍān yā nūr","ar":"رمضان يا نور","en":"Ramadan, o light"},{"en":"thirty days of mercy with the gate left open"},{"en":"we are hungry and we have never been happier"},{"tr":"Ramaḍān yā nūr, yā nūr al-bayt","ar":"رمضان يا نور، يا نور البيت","en":"Ramadan, o light — light of the house"}]'::jsonb, null,
   null, null, null, 100304, null, 'live', now() - interval '607 days', 29401, 1108, 0),
  ('sng_laylat-al-qadr', '21f49ce5-69d5-4d23-a032-260eabbac935', 'Laylat al-Qadr', 'ليلة القدر', 'For the odd nights of the last ten. Fifty-four beats a minute, because the angels descending are in no hurry.',
   'saba', 50, 54, 'duet', null, 'verse',
   2, 'cobalt', 2023, array['ramadan', 'night', 'stillness', 'duet']::text[], '[{"tr":"Laylatu al-Qadri khayrun min alfi shahr","ar":"لَيْلَةُ القَدْرِ خَيْرٌ مِنْ أَلْفِ شَهْرٍ","en":"The Night of Decree is better than a thousand months","note":"Qurʾān 97:3"},{"en":"and the night is quiet as a held breath"},{"tr":"Tanazzalu al-malāʾikatu fīhā","ar":"تَنَزَّلُ المَلَائِكَةُ فِيهَا","en":"The angels descend in it","note":"Qurʾān 97:4"},{"en":"with every mercy we did not earn"},{"tr":"Salāmun hiya ḥattā maṭlaʿi al-fajr","ar":"سَلَامٌ هِيَ حَتَّى مَطْلَعِ الفَجْرِ","en":"Peace it is, until the rising of dawn","note":"Qurʾān 97:5"},{"en":"peace, until the rising of the dawn"}]'::jsonb, null,
   null, null, null, 155778, null, 'live', now() - interval '636 days', 29490, 1022, 0),
  ('sng_eid-mubarak', '708aefa0-2a83-42c1-b120-74393eb8838f', 'ʿĪd Mubārak', 'عيد مبارك', 'The ensemble''s ʿĪd opener — children on the duff, everyone else clapping behind the beat on purpose.',
   'ajam', 57, 104, 'choir', 'D..TD..TD..TD..T', 'intro',
   3, 'jade', 2019, array['eid', 'celebration', 'duff', 'choir']::text[], '[{"tr":"ʿĪdun mubārak, ʿīdun saʿīd","ar":"عيد مبارك، عيد سعيد","en":"A blessed feast, a joyful feast","note":"traditional greeting"},{"en":"the new clothes smell like everyone''s house"},{"en":"sugar on the table, sugar on the street"},{"tr":"Taqabbala Allāhu minnā wa minkum","ar":"تقبّل الله منّا ومنكم","en":"May Allah accept from us and from you","note":"traditional greeting"},{"en":"we forgive the year, the year forgives us"},{"tr":"ʿĪdun mubārak, ʿīdun saʿīd","ar":"عيد مبارك، عيد سعيد","en":"A blessed feast, a joyful feast"}]'::jsonb, null,
   null, null, null, 115096, null, 'live', now() - interval '689 days', 31337, 1205, 0),
  ('sng_the-night-journey', '81a8cef1-c501-4fa7-bb04-aab67d6430cf', 'al-Isrāʾ: The Night Journey', 'الإسراء', 'A storytelling nasheed in Nikrīz — cool and reflective, with a drum that only enters on the ascent.',
   'nikriz', 52, 80, 'duet', null, 'verse',
   2, 'cobalt', 2024, array['original', 'story', 'night', 'duet']::text[], '[{"en":"From the sacred house to the further one","note":"original"},{"en":"in a part of the night, while the city slept"},{"tr":"Subḥāna alladhī asrā bi-ʿabdih","ar":"سُبْحَانَ الَّذِي أَسْرَى بِعَبْدِهِ","en":"Glory to Him who carried His servant by night","note":"Qurʾān 17:1"},{"en":"the sky opened like a page being turned"},{"en":"and every prophet stood to greet him"},{"en":"then he came back down to a borrowed bed"}]'::jsonb, null,
   null, null, null, 108150, null, 'live', now() - interval '726 days', 13753, 425, 0),
  ('sng_dust-and-light', '3782b37c-b00f-4146-83f7-0d2934b37ddb', 'Dust and Light', null, 'Four minutes of one voice thinking out loud about being made of dust.',
   'kurd', 50, 66, 'solo', null, 'verse',
   2, 'turq', 2022, array['original', 'reflective', 'solo', 'minimal']::text[], '[{"en":"I am dust that learned to speak","note":"original"},{"en":"and light that keeps forgetting where it came from"},{"en":"between those two I built a life"},{"tr":"Yā Allāh","ar":"يا الله","en":"O Allah"},{"en":"the dust is not ashamed of being dust"},{"en":"so let the light stop asking to be more"}]'::jsonb, null,
   null, null, null, 123818, null, 'live', now() - interval '776 days', 37171, 1005, 0),
  ('sng_alhamdulillah', '3782b37c-b00f-4146-83f7-0d2934b37ddb', 'Alḥamdulillāh', 'الحمد لله', 'Gratitude with a pulse — the track people put on while cooking.',
   'ajam', 55, 84, 'duet', 'D...T...D...T...', 'verse',
   2, 'jade', 2021, array['dhikr', 'gratitude', 'duff', 'duet']::text[], '[{"tr":"Alḥamdulillāhi Rabbi al-ʿālamīn","ar":"الحمدُ للهِ ربِّ العالمين","en":"Praise belongs to Allah, Lord of all worlds","note":"Qurʾān 1:2"},{"en":"for the water, for the door, for the breath"},{"tr":"Alḥamdulillāh","ar":"الحمد لله","en":"Praise be to Allah"},{"en":"for the ordinary mercy of a Tuesday"},{"tr":"Alḥamdulillāh ʿalā kulli ḥāl","ar":"الحمدُ للهِ على كلّ حال","en":"Praise be to Allah in every condition","note":"dhikr"},{"en":"for the good and the thing that was not"}]'::jsonb, null,
   null, null, null, 103000, null, 'live', now() - interval '807 days', 26984, 1236, 0),
  ('sng_letters-to-madinah', '81a8cef1-c501-4fa7-bb04-aab67d6430cf', 'Letters to Madinah', 'رسائل إلى المدينة', 'Written in Sarajevo in February by someone who has never been. Ḥijāz does that to people.',
   'hijaz', 55, 68, 'solo', null, 'verse',
   2, 'gold', 2023, array['original', 'longing', 'solo', 'hijaz']::text[], '[{"en":"I write to a city I have never seen","note":"original"},{"en":"and post it with the salām on my lips"},{"tr":"Salāmun ʿalayka yā Ṭaybah","ar":"سلامٌ عليك يا طيبة","en":"Peace be upon you, O Ṭaybah"},{"en":"there is snow on the window and green in the glass"},{"en":"one day I will walk where the words go"},{"tr":"Salāmun ʿalayka yā Ṭaybah","ar":"سلامٌ عليك يا طيبة","en":"Peace be upon you, O Ṭaybah"}]'::jsonb, null,
   null, null, null, 127235, null, 'live', now() - interval '869 days', 31066, 875, 0),
  ('sng_before-the-dawn', '81a8cef1-c501-4fa7-bb04-aab67d6430cf', 'Before the Dawn', null, 'For the hour before Fajr when the house is cold and the duʿāʾ is easy.',
   'bayati', 53, 60, 'duet', null, 'verse',
   2, 'cobalt', 2024, array['original', 'dawn', 'dua', 'duet']::text[], '[{"en":"Before the dawn there is an hour","note":"original"},{"en":"when the asking is its own answer"},{"tr":"Yā Rabb al-ʿālamīn","ar":"يا ربّ العالمين","en":"O Lord of all worlds"},{"en":"I have been sleeping on my own life"},{"en":"wake me in the part of the night You kept"},{"tr":"Yā Rabb al-ʿālamīn","ar":"يا ربّ العالمين","en":"O Lord of all worlds"}]'::jsonb, null,
   null, null, null, 132200, null, 'live', now() - interval '906 days', 25464, 1109, 0),
  ('sng_ya-habib-al-qalb', 'd26f258b-7b1d-452b-bf5a-7947d45fb56b', 'Yā Ḥabīb al-Qalb', 'يا حبيب القلب', 'An original salām in Bayātī. The second voice only appears on the third line and never explains itself.',
   'bayati', 57, 64, 'duet', null, 'verse',
   2, 'jade', 2022, array['original', 'longing', 'duet', 'hijaz']::text[], '[{"tr":"Yā ḥabība al-qalb, yā nūr al-ʿayn","ar":"يا حبيبَ القلب، يا نورَ العين","en":"O beloved of the heart, o light of the eye","note":"original"},{"en":"the world is loud and you are the quiet in it"},{"tr":"Ṣallā Allāhu ʿalayka","ar":"صلّى الله عليك","en":"May Allah bless you"},{"en":"we mention you and the room becomes a garden"},{"tr":"Yā ḥabība al-qalb","ar":"يا حبيبَ القلب","en":"O beloved of the heart"},{"en":"teach the tongue to be gentle like yours"}]'::jsonb, null,
   null, null, null, 135187, null, 'live', now() - interval '930 days', 9024, 391, 0),
  ('sng_allahu-akbar-kabira', 'f25def6c-4b05-46c7-9412-8a36a7defa71', 'Allāhu Akbar Kabīrā', 'الله أكبر كبيرًا', 'The ʿĪd takbīr as the Night Choir does it — full chest, rolling drum, absolutely no hurry on the last line.',
   'rast', 52, 96, 'choir', 'D..T..D.T..T.D..', 'intro',
   3, 'gold', 2024, array['dhikr', 'takbir', 'duff', 'choir']::text[], '[{"tr":"Allāhu akbar kabīrā","ar":"اللهُ أكبرُ كبيرًا","en":"Allah is greatest, greatly","note":"takbīr"},{"tr":"wa-l-ḥamdu lillāhi kathīrā","ar":"والحمدُ للهِ كثيرًا","en":"and praise belongs to Allah, abundantly"},{"tr":"wa subḥāna Allāhi bukratan wa aṣīlā","ar":"وسبحانَ اللهِ بكرةً وأصيلًا","en":"and glory to Allah, morning and evening"},{"tr":"Lā ilāha illā Allāh waḥdah","ar":"لا إله إلا اللهُ وحدَه","en":"There is no god but Allah, alone"},{"tr":"Ṣadaqa waʿdah wa naṣara ʿabdah","ar":"صدقَ وعدَه ونصرَ عبدَه","en":"He fulfilled His promise and aided His servant"},{"tr":"Allāhu akbar, Allāhu akbar","ar":"اللهُ أكبر، اللهُ أكبر","en":"Allah is greatest, Allah is greatest"}]'::jsonb, null,
